/*
 Problem: 921. Minimum Add to Make Parentheses Valid
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 8.5 MB (56.27%)
 Tags: String, Stack, Greedy, Bracket Sequences
*/
class Solution {
public:
    int minAddToMakeValid(string s) {
        int l = 0, r = 0;
        for (const auto& c : s) {
            bool isLeft = (c == '(');
            l += isLeft;
            (l > 0) ? l -= (!isLeft) : r += (!isLeft);
        }
        return l + r;
    }
};
